import json
import os
import re
import subprocess
import tempfile
from typing import List, Dict

import whisper

INPUT_PATH = "/root/input.mp4"
ANNOTATIONS_PATH = "/root/annotations.json"
OUTPUT_PATH = "/root/output.mp4"

SINGLE_WORDS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "kind", "basically",
    "well", "okay",
}

# Phrases are matched as exact sequences of normalized tokens
PHRASES = [
    "you know",
    "i mean",
    "kind of",
    "i guess",
]

PAD_BEFORE = 0.05
PAD_AFTER = 0.05


def run_cmd(cmd: List[str]) -> str:
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"Command failed: {' '.join(cmd)}\n{result.stderr}")
    return result.stdout.strip()


def get_duration(path: str) -> float:
    out = run_cmd([
        "ffprobe", "-v", "error",
        "-show_entries", "format=duration",
        "-of", "default=noprint_wrappers=1:nokey=1",
        path,
    ])
    try:
        return float(out)
    except ValueError:
        return 0.0


def get_video_size(path: str):
    out = run_cmd([
        "ffprobe", "-v", "error",
        "-select_streams", "v:0",
        "-show_entries", "stream=width,height",
        "-of", "csv=p=0:s=x",
        path,
    ])
    if "x" in out:
        w, h = out.split("x")
        try:
            return int(w), int(h)
        except ValueError:
            return None
    return None


def normalize_token(token: str) -> str:
    clean = re.sub(r"[^a-z0-9]", "", token.lower())
    if clean == "im":
        return "i"
    if clean == "ok":
        return "okay"
    return clean


def transcribe_words(path: str) -> List[Dict]:
    model = whisper.load_model("tiny")
    result = model.transcribe(path, word_timestamps=True, language="en")

    words = []
    for segment in result.get("segments", []):
        for word_info in segment.get("words", []):
            raw = word_info.get("word", "")
            clean = normalize_token(raw)
            if not clean:
                continue
            words.append({
                "raw": raw,
                "clean": clean,
                "start": float(word_info.get("start", 0.0)),
                "end": float(word_info.get("end", 0.0)),
            })
    return words


def detect_fillers(words: List[Dict]) -> List[Dict]:
    matches = []

    # Phrase matches
    for phrase in PHRASES:
        tokens = phrase.split()
        n = len(tokens)
        for i in range(0, len(words) - n + 1):
            if all(words[i + j]["clean"] == tokens[j] for j in range(n)):
                start = words[i]["start"]
                end = words[i + n - 1]["end"]
                matches.append({
                    "word": phrase,
                    "start": start,
                    "end": end,
                })

    # Single word matches
    for w in words:
        if w["clean"] in SINGLE_WORDS:
            matches.append({
                "word": w["clean"],
                "start": w["start"],
                "end": w["end"],
            })

    matches.sort(key=lambda m: m["start"])
    return matches


def write_annotations(matches: List[Dict], path: str) -> None:
    annotations = [
        {"word": m["word"], "timestamp": round(m["start"], 2)}
        for m in matches
    ]
    with open(path, "w") as f:
        json.dump(annotations, f, indent=2)


def build_filler_clips(matches: List[Dict], input_path: str, output_path: str) -> None:
    if not matches:
        size = get_video_size(input_path) or (1280, 720)
        w, h = size
        # Create a short silent placeholder when no fillers are found.
        subprocess.run([
            "ffmpeg", "-y",
            "-f", "lavfi", "-i", f"color=c=black:s={w}x{h}:d=0.1",
            "-f", "lavfi", "-i", "anullsrc=channel_layout=stereo:sample_rate=44100",
            "-shortest",
            "-c:v", "libx264", "-c:a", "aac",
            "-movflags", "+faststart",
            output_path,
        ], check=True)
        return

    duration = get_duration(input_path)

    temp_dir = tempfile.mkdtemp(prefix="filler_clips_")
    clip_paths = []

    for i, m in enumerate(matches):
        start = max(0.0, m["start"] - PAD_BEFORE)
        end = m["end"] + PAD_AFTER
        if duration > 0:
            end = min(duration, end)
        if end <= start:
            continue
        clip_dur = max(0.02, end - start)

        clip_path = os.path.join(temp_dir, f"clip_{i:05d}.mp4")
        cmd = [
            "ffmpeg", "-y",
            "-i", input_path,
            "-ss", f"{start:.3f}",
            "-t", f"{clip_dur:.3f}",
            "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
            "-c:a", "aac", "-b:a", "128k",
            "-movflags", "+faststart",
            clip_path,
        ]
        subprocess.run(cmd, check=True)
        clip_paths.append(clip_path)

    list_path = os.path.join(temp_dir, "concat_list.txt")
    with open(list_path, "w") as f:
        for p in clip_paths:
            f.write(f"file '{p}'\n")

    subprocess.run([
        "ffmpeg", "-y",
        "-f", "concat", "-safe", "0",
        "-i", list_path,
        "-c", "copy",
        output_path,
    ], check=True)


if __name__ == "__main__":
    words = transcribe_words(INPUT_PATH)
    matches = detect_fillers(words)
    write_annotations(matches, ANNOTATIONS_PATH)
    build_filler_clips(matches, INPUT_PATH, OUTPUT_PATH)
